/**
 * MCP Dev Server
 *
 * Exposes dev server functionality via MCP (Model Context Protocol).
 * Supports stdio transport for local editors and loopback HTTP transport for
 * browser integrations during `veryfront dev`.
 */
import { cwd, readTextFile } from "../../src/platform/index.js";
import { createHttpServer } from "../../src/platform/compat/http/index.js";
import { cliLogger } from "../utils/index.js";
import { withSpan } from "../../src/observability/tracing/otlp-setup.js";
import { createIssuesManager } from "../../src/issues/index.js";
import { getErrorCollector } from "../../src/observability/error-collector.js";
import { getLogBuffer } from "../../src/observability/log-buffer.js";
import { isRequestBodyTooLargeError, readBodyWithLimit } from "../../src/security/index.js";
import { zodToJsonSchema } from "../../src/tool/schema/index.js";
