                veryfront: ["veryfront", "SKILL.md"],
                "veryfront-routing": ["veryfront", "references/ROUTES.md"],
                "veryfront-ai-tools": ["veryfront", "references/AI-TOOLS.md"],
                "veryfront-components": ["veryfront", "references/COMPONENTS.md"],
